import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;
  const root = new Group();
  root.name = 'hero-headline';

  const ownedGeometries = [];
  const ownedMaterials = [];
  const ownedTextures = [];
  const primitiveResults = [];
  const timelines = [];

  const makeBasicMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.push(material);
    return material;
  };

  const gradientMaterial = makeBasicMaterial();
  const gradientUv = uv();
  const upperGradient = mix(
    color('#0b0b10'),
    color('#16161d'),
    smoothstep(0.05, 0.95, gradientUv.y)
  );
  gradientMaterial.colorNode = mix(
    upperGradient,
    color('#ff2a38'),
    smoothstep(0.88, 1.0, gradientUv.y).mul(0.055)
  );

  const backdropGeometry = new PlaneGeometry(7, 6);
  ownedGeometries.push(backdropGeometry);

  const backdrop = new Mesh(backdropGeometry, gradientMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  backdrop.renderOrder = -10;
  root.add(backdrop);

  const imageMaterial = makeBasicMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 0.98
  });

  const imageGeometry = new PlaneGeometry(4.55, 2.55);
  ownedGeometries.push(imageGeometry);

  const imagePanel = new Mesh(imageGeometry, imageMaterial);
  imagePanel.name = 'hero-image-panel';
  imagePanel.position.set(0.65, -0.05, 0.05);
  imagePanel.renderOrder = 1;
  root.add(imagePanel);

  const frameMaterial = makeBasicMaterial({ color: '#e8ecf2' });
  const frameDepth = 0.035;

  const frameTopGeometry = new BoxGeometry(4.75, frameDepth, 0.045);
  const frameBottomGeometry = new BoxGeometry(4.75, frameDepth, 0.045);
  const frameSideGeometry = new BoxGeometry(frameDepth, 2.65, 0.045);

  ownedGeometries.push(
    frameTopGeometry,
    frameBottomGeometry,
    frameSideGeometry
  );

  const frameTop = new Mesh(frameTopGeometry, frameMaterial);
  frameTop.position.set(0.65, 1.28, 0.09);

  const frameBottom = new Mesh(frameBottomGeometry, frameMaterial);
  frameBottom.position.set(0.65, -1.38, 0.09);

  const frameLeft = new Mesh(frameSideGeometry, frameMaterial);
  frameLeft.position.set(-1.72, -0.05, 0.09);

  const frameRight = new Mesh(frameSideGeometry, frameMaterial);
  frameRight.position.set(3.02, -0.05, 0.09);

  root.add(frameTop, frameBottom, frameLeft, frameRight);

  const accentMaterial = makeBasicMaterial({ color: '#ff2a38' });
  const accentGeometry = new BoxGeometry(0.82, 0.045, 0.055);
  ownedGeometries.push(accentGeometry);

  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.name = 'signal-red-accent';
  accentBar.position.set(-2.65, 1.04, 0.2);
  accentBar.renderOrder = 4;
  root.add(accentBar);

  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  let textOffset = 0.55;

  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const typography = item.typography ?? {};
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: typography.fontSize ?? 31,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 430,
      letterSpacingPx: typography.letterSpacingPx
    });

    textObject.name = `hero-text-${item.role ?? 'body'}`;
    textObject.position.set(-2.65, textOffset, 0.28);
    textObject.renderOrder = 5;
    root.add(textObject);

    textOffset -= item.role === 'body' ? 0.62 : 0.42;
  }

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((texture) => {
        if (root.userData.cleaned) {
          texture.dispose?.();
          return;
        }

        ownedTextures.push(texture);
        imageMaterial.map = texture;
        imageMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  const entrance = gsap.timeline();
  timelines.push(entrance);
  entrance.fromTo(
    root.scale,
    { x: 0.985, y: 0.985, z: 0.985 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.7,
      ease: 'power3.out'
    }
  );

  for (const primitive of config.cinematicPrimitives ?? []) {
    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result) primitiveResults.push(result);
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    for (const texture of ownedTextures) {
      texture.dispose?.();
    }

    for (const material of ownedMaterials) {
      material.dispose?.();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    root.clear();
  };

  return root;
}
